'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useTranslations } from 'next-intl';
import JournalEntrySlideOver, { JournalEntry } from './journal-entries/JournalEntrySlideOver';
import CodesModal from './CodesModal';
import DataGrid from '@/components/DataGrid';
import type { ColDef } from 'ag-grid-community';

interface AccountOption {
  accountCode: string;
  name: string;
}

interface GlEntry {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  entryMemo: string | null;
  sourceType: string;
  sourceId: string | null;
  accountCode: string;
  accountName: string;
  partyType: string | null;
  partyId: string | null;
  debit: string;
  credit: string;
  lineMemo: string | null;
  createdBy: string | null;
  createdOn: string | null;
}

const PAGE_SIZE = 200;

export default function GeneralLedgerContent() {
  const t = useTranslations('gl.generalLedger');
  const tCodes = useTranslations('gl.codes');
  const tCommon = useTranslations('common');
  const tGrid = useTranslations('common.grid');

  function fmt(v: string | number | null | undefined) {
    if (!v) return tCommon('na');
    const n = typeof v === 'string' ? parseFloat(v) : v;
    if (!n || n === 0) return tCommon('na');
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  const [accounts, setAccounts] = useState<AccountOption[]>([]);
  const [accountCode, setAccountCode] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [selectedEntry, setSelectedEntry] = useState<JournalEntry | null>(null);

  // Manual pagination state (so we control it from the header, not the DataGrid overlay)
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [rows, setRows] = useState<GlEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCodesOpen, setIsCodesOpen] = useState(false);

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  useEffect(() => {
    api.glControllerGetAccounts({ format: 'flat' })
      .then(res => {
        const data = res.data || [];
        const leafAccounts = data.filter((a: unknown) => !(a as { isGroup: boolean }).isGroup);
        setAccounts(leafAccounts.map((a: unknown) => ({ accountCode: (a as { accountCode: string }).accountCode, name: (a as { name: string }).name })));
      })
      .catch((err) => reportError(err, 'GeneralLedgerPage'));
  }, []);

  // Reset page to 1 when filters change
  useEffect(() => { setPage(1); }, [accountCode, fromDate, toDate]);

  // Fetch GL data
  const fetchData = useCallback(() => {
    setLoading(true);
    const params = new URLSearchParams();
    if (accountCode) params.set('account', accountCode);
    if (fromDate) params.set('fromDate', fromDate);
    if (toDate) params.set('toDate', toDate);
    params.set('page', String(page));
    params.set('limit', String(PAGE_SIZE));
    const qs = params.toString() ? `?${params}` : '';
    api.glControllerGetGeneralLedger({ 
      account: accountCode, 
      fromDate: fromDate, 
      toDate: toDate, 
      page: page.toString(), 
      limit: PAGE_SIZE.toString() 
    })
      .then((res) => {
        const payload = res.data;
        setRows((payload as any).data as unknown as GlEntry[]);
        setTotal((payload as any).total || 0);
      })
      .catch((err) => reportError(err, 'GeneralLedgerContent'))
      .finally(() => setLoading(false));
  }, [accountCode, fromDate, toDate, page]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const columns = useMemo<ColDef[]>(() => [
    { 
      field: 'entryDate', 
      headerName: t('columns.date'), 
      width: 120,
      valueFormatter: (p: any) => p.value ? new Date(p.value).toLocaleDateString() : ''
    },
    { 
      field: 'entryNumber', 
      headerName: t('columns.entryNumber'), 
      width: 140, 
      pinned: 'left',
      cellStyle: { fontWeight: 'bold', color: 'var(--accent)', cursor: 'pointer' }
    },
    {
      field: 'accountCode',
      headerName: t('columns.customer'),
      width: 250,
      cellRenderer: (p: any) => {
        return (
          <span>
            <span className="font-mono text-gray-400 mr-2">{p.value}</span>
            {p.data.accountName}
          </span>
        );
      }
    },
    { 
      field: 'lineMemo', 
      headerName: t('columns.memo'), 
      flex: 1, 
      minWidth: 200,
      valueGetter: (p: any) => p.data.lineMemo || p.data.entryMemo || ''
    },
    { 
      field: 'debit', 
      headerName: t('columns.debit'), 
      width: 120,
      cellClass: 'text-right font-mono',
      valueFormatter: (p: any) => fmt(p.value)
    },
    { 
      field: 'credit', 
      headerName: t('columns.credit'), 
      width: 120,
      cellClass: 'text-right font-mono',
      valueFormatter: (p: any) => fmt(p.value)
    }
  ], [t, tCommon]);

  // We manage data externally, so we feed it directly to DataGrid via fetchAll + a dummy endpoint
  // Actually, we'll bypass DataGrid's own fetching by providing the data externally.
  // Since DataGrid always fetches, we'll use its renderHeader but handle data ourselves.

  return (
    <>
    <DataGrid<GlEntry>
      endpoint={`/api/gl/general-ledger?account=${accountCode}&fromDate=${fromDate}&toDate=${toDate}`}
      columns={columns}
      gridKey="gl-general-ledger"
      exportFileName="general-ledger"
      fetchAll={true}
      onRowClicked={(row) => {
        setSelectedEntry({
          journalEntryId: row.journalEntryId,
          entryNumber: row.entryNumber,
          entryDate: row.entryDate,
          memo: row.entryMemo,
          sourceType: row.sourceType || 'manual',
          sourceId: row.sourceId || null,
          createdBy: row.createdBy || null,
        });
      }}
      pageTitle={t('title')}
      headerFilters={
        <>
          <select
            value={accountCode}
            onChange={(e) => setAccountCode(e.target.value)}
            className="input text-xs h-9 border-gray-200 w-auto min-w-[200px] bg-white rounded-lg"
          >
            <option value="">{t('allAccounts')}</option>
            {accounts.map((a) => (
              <option key={a.accountCode} value={a.accountCode}>
                {a.accountCode} ΓÇö {a.name}
              </option>
            ))}
          </select>

          <div className="flex items-center gap-3">
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              className="input text-xs h-9 border-gray-200 bg-white px-3 text-gray-500 rounded-lg w-auto"
              title={t('fromDate')}
            />
            <span className="text-gray-300 font-bold">ΓåÆ</span>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              className="input text-xs h-9 border-gray-200 bg-white px-3 text-gray-500 rounded-lg w-auto"
              title={t('toDate')}
            />
          </div>
        </>
      }
      headerActions={
        <button
          onClick={() => setIsCodesOpen(true)}
          className="btn btn-secondary btn-sm whitespace-nowrap"
        >
          {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="material-symbols-outlined text-sm">visibility</span>
          {/* eslint-enable i18next/no-literal-string */}
          {tCodes('button')}
        </button>
      }
    />

      <JournalEntrySlideOver
        entry={selectedEntry}
        onClose={() => setSelectedEntry(null)}
      />

      <CodesModal 
        isOpen={isCodesOpen}
        onClose={() => setIsCodesOpen(false)}
      />
    </>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import Link from 'next/link';

export interface JournalEntry {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  memo: string | null;
  sourceType: string;
  sourceId: string | null;
  createdBy: string | null;
}

export interface JournalLine {
  journalLineId: string;
  accountCode?: string;
  accountName?: string;
  partyType?: string | null;
  partyId?: string | null;
  partyName?: string | null;
  debit: string;
  credit: string;
  memo: string | null;
}

interface JournalEntrySlideOverProps {
  entry: JournalEntry | null;
  onClose: () => void;
}

export default function JournalEntrySlideOver({ entry, onClose }: JournalEntrySlideOverProps) {
  const t = useTranslations('gl.journalEntries');
  const tCommon = useTranslations('common');

  function fmt(v: string | number) {
    const n = typeof v === 'string' ? parseFloat(v) : v;
    if (!n || n === 0) return tCommon('na');
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  const [lines, setLines] = useState<JournalLine[]>([]);
  const [loading, setLoading] = useState(false);

  const sourceLabel = (type: string) => {
    const labels: Record<string, string> = {
      sales_invoice: t('sourceSalesInvoice'),
      purchase_invoice: t('sourcePurchaseInvoice'),
      sales_credit_note: t('sourceSalesCreditNote'),
      manual: t('sourceManual'),
    };
    return labels[type] || type;
  };

  useEffect(() => {
    if (!entry) {
      setLines([]);
      return;
    }

    setLoading(true);
    api.glControllerGetJournalEntry(entry.journalEntryId)
      .then((res) => {
        const detail = res.data as any;
        setLines(detail.lines || []);
      })
      .catch((err) => reportError(err, 'JournalEntrySlideOver'))
      .finally(() => setLoading(false));
  }, [entry]);

  return (
    <SlideOver
      isOpen={!!entry}
      onClose={onClose}
      title={entry ? entry.entryNumber : t('title')}
      subtitle={entry ? `${new Date(entry.entryDate).toLocaleDateString()} ┬╖ ${sourceLabel(entry.sourceType)}` : undefined}
      width="max-w-3xl"
    >
      {entry && (
        <div className="space-y-6">
          <div className="card space-y-5">
            <div className="flex flex-col gap-5 text-sm">
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('columns.memo')}</span>
                <span className="text-[#041627]">{entry.memo || tCommon('na')}</span>
              </div>
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('sourceDocument')}</span>
                {entry.sourceId && (entry.sourceType === 'sales_invoice' || entry.sourceType === 'sales_credit_note') ? (
                  <Link 
                    href={`/sales-orders/${entry.sourceId}${entry.sourceType === 'sales_invoice' ? '#invoices-section' : ''}`} 
                    className="text-[var(--accent)] hover:underline"
                    onClick={onClose}
                  >
                    {sourceLabel(entry.sourceType)}
                  </Link>
                ) : (
                  <span className="text-[#041627]">{sourceLabel(entry.sourceType)}</span>
                )}
              </div>
            </div>
          </div>

          <div className="rounded-xl border border-gray-200 overflow-hidden bg-white">
            {loading ? (
              <div className="flex justify-center items-center py-12">
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="loading loading-spinner text-gray-400"></span>
              </div>
            ) : (
              <table className="w-full text-sm text-left">
                <thead className="bg-[#f8f9fa] border-b border-gray-200 text-[#041627] font-semibold text-xs uppercase tracking-wider">
                  <tr>
                    <th className="px-5 py-3">{t('columns.customer')}</th>
                    <th className="px-5 py-3">{t('columns.party')}</th>
                    <th className="px-5 py-3 text-right">{t('columns.debit')}</th>
                    <th className="px-5 py-3 text-right">{t('columns.credit')}</th>
                    <th className="px-5 py-3">{t('columns.memo')}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {lines.map((l) => (
                    <tr key={l.journalLineId} className="hover:bg-gray-50/50 transition-colors">
                      <td className="px-5 py-3">
                        <div className="font-mono text-xs text-gray-500">{l.accountCode}</div>
                        <div className="font-semibold text-[#041627] mt-0.5">{l.accountName}</div>
                      </td>
                      <td className="px-5 py-3 text-xs">
                        {l.partyType && l.partyId ? (
                          <Link 
                            href={`/${l.partyType === 'customer' ? 'accounts' : 'suppliers'}/${l.partyId}`}
                            className="text-[var(--accent)] hover:underline"
                            onClick={onClose}
                          >
                            {l.partyName || (l.partyId ? `${l.partyType}: ${l.partyId.substring(0, 8)}...` : l.partyType)}
                          </Link>
                        ) : l.partyType ? (
                          <span className="text-gray-600">
                            {l.partyType}: {l.partyId?.substring(0, 8)}...
                          </span>
                        ) : tCommon('na')}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-medium text-[#041627]">
                        {fmt(l.debit)}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-medium text-[#041627]">
                        {fmt(l.credit)}
                      </td>
                      <td className="px-5 py-3 text-gray-500 text-xs">
                        {l.memo || tCommon('na')}
                      </td>
                    </tr>
                  ))}
                  {/* Totals Row */}
                  {lines.length > 0 && (
                    <tr className="bg-[#f8f9fa] border-t-2 border-gray-200">
                      <td colSpan={2} className="px-5 py-3 text-right font-bold text-[#041627] text-xs uppercase tracking-wider">
                        {t('total')}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-bold text-[#041627]">
                        {fmt(lines.reduce((s, l) => s + parseFloat(l.debit || '0'), 0))}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-bold text-[#041627]">
                        {fmt(lines.reduce((s, l) => s + parseFloat(l.credit || '0'), 0))}
                      </td>
                      <td></td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
            {!loading && lines.length === 0 && (
              <div className="p-8 text-center text-gray-500 text-sm">
                {t('noLines')}
              </div>
            )}
          </div>
        </div>
      )}
    </SlideOver>
  );
}

