'use client';

import React, { use, useState, useEffect, useMemo, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import DataGrid from '@/components/DataGrid';
import type { ColDef } from 'ag-grid-community';
import QuickAdjustmentModal from './QuickAdjustmentModal';
import SplitEntryModal from './SplitEntryModal';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import toast from 'react-hot-toast';
import { useTranslations } from 'next-intl';
import BankMatchingView from './BankMatchingView';
import { getErrorMessage } from '@modbm/shared';

const ToggleCell = (p: any) => {
  const t = useTranslations('gl.reconciliations');
  const data = p.data;
  const context = p.context;
  
  if (!data || !context) return null;
  const { handleToggle, isPosted } = context;

  const handleToggleClick = () => {
    handleToggle(data.journalLineId, !data.isCleared);
  };

  return (
    <div className="flex items-center gap-3 mt-1">
      <button
        type="button"
        disabled={isPosted}
        onClick={handleToggleClick}
        className={`relative inline-flex h-5 w-9 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${
          data.isCleared ? 'bg-[var(--accent)]' : 'bg-gray-300'
        } ${isPosted ? 'opacity-50 cursor-not-allowed' : ''}`}
        aria-checked={data.isCleared}
        role="switch"
        title={data.isCleared ? t('tooltips.clickToUnclear') : t('tooltips.clickToClear')}
      >
        <span
          aria-hidden="true"
          className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
            data.isCleared ? 'translate-x-4' : 'translate-x-0'
          }`}
        />
      </button>
    </div>
  );
};

export default function ReconciliationDetailsPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const t = useTranslations('gl.reconciliations');
  const tCommon = useTranslations('common');
  useDocumentTitle(t('detailsTitle'));
  const router = useRouter();
  
  const [reconciliation, setReconciliation] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [posting, setPosting] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [isAdjustmentModalOpen, setAdjustmentModalOpen] = useState(false);
  const [isSplitModalOpen, setSplitModalOpen] = useState(false);
  const [selectedRow, setSelectedRow] = useState<any>(null);
  const [viewMode, setViewMode] = useState<'bank' | 'ledger'>('bank');

  const fetchDetails = useCallback(async () => {
    try {
      const recRes = await api.reconciliationControllerGetReconciliation(id);
      setReconciliation(recRes.data );
    } catch (err) {
      reportError(err, 'ReconciliationDetails');
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => {
    fetchDetails();
  }, [fetchDetails]);

  const handleToggle = async (lineId: string, isCleared: boolean, amount?: number) => {
    try {
      await api.reconciliationControllerToggleLine(id, lineId, { isCleared, amount });
      // Refresh details to update variance and lines
      fetchDetails();
      setRefreshKey(k => k + 1);
      
      if (selectedRow && selectedRow.journalLineId === lineId) {
        setSelectedRow({ ...selectedRow, isCleared });
      }
    } catch (err) {
      reportError(err, 'ReconciliationToggle');
      toast.error(t('toggleError'));
    }
  };

  const handlePost = async () => {
    if (!confirm(t('confirmPost'))) return;
    
    setPosting(true);
    try {
      await api.reconciliationControllerPostReconciliation(id, {});
      toast.success(t('postSuccess'));
      router.push('/general-ledger/reconciliations');
    } catch (err) {
      reportError(err, 'ReconciliationPost');
      toast.error(t('postError'));
    } finally {
      setPosting(false);
    }
  };

  const handleDiscard = async () => {
    if (!confirm(t('confirmDiscard'))) return;
    
    setPosting(true);
    try {
      await api.reconciliationControllerDiscardReconciliation(id);
      toast.success(t('discardSuccess'));
      router.push('/general-ledger/reconciliations');
    } catch (err: unknown) {
      reportError(err, 'ReconciliationDiscard');
      toast.error(getErrorMessage(err) || t('discardError'));
      setPosting(false);
    }
  };

  const columns = useMemo<ColDef[]>(() => {
    const isPosted = reconciliation?.status === 'posted';
    
    return [
      { 
        field: 'entryDate', 
        headerName: t('columns.date'), 
        width: 140,
        comparator: (valueA, valueB, nodeA, nodeB, isDescending) => {
          if (valueA === valueB) {
            // If dates are identical, fallback to a strict logic:
            // 1. Keep children after their parents by comparing sourceId
            if (nodeA.data?.sourceId === nodeB.data?.journalLineId) return isDescending ? -1 : 1;
            if (nodeB.data?.sourceId === nodeA.data?.journalLineId) return isDescending ? 1 : -1;
            
            // 2. If they are siblings (same sourceId), sort by Memo (Reversal, Split A, Split B)
            if (nodeA.data?.sourceId && nodeA.data?.sourceId === nodeB.data?.sourceId) {
              const memoA = nodeA.data.memo || '';
              const memoB = nodeB.data.memo || '';
              
              const getRank = (m: string) => {
                if (m.startsWith('Reversal')) return 1;
                if (m.startsWith('Split A')) return 2;
                if (m.startsWith('Split B')) return 3;
                return 4;
              };
              
              return getRank(memoA) - getRank(memoB);
            }
            
            // 3. Fallback to createdAt or entryNumber
            return (nodeA.data?.entryNumber || '').localeCompare(nodeB.data?.entryNumber || '');
          }
          return (valueA || '').localeCompare(valueB || '');
        }
      },
      { field: 'entryNumber', headerName: t('columns.entryNo'), width: 150 },
      { 
        field: 'partyName', 
        headerName: t('columns.party'), 
        width: 150,
        valueGetter: (p: any) => p.data?.partyName || p.data?.partyId || ''
      },
      { field: 'memo', headerName: t('columns.memo'), flex: 1 },
      { 
        field: 'debit', 
        headerName: t('columns.debit'), 
        width: 120,
        valueFormatter: (p) => p.value ? new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(p.value) : ''
      },
      { 
        field: 'credit', 
        headerName: t('columns.credit'), 
        width: 120,
        valueFormatter: (p) => p.value ? new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(p.value) : ''
      },
      {
        headerName: t('columns.cleared'),
        cellRenderer: ToggleCell,
        width: 100,
        suppressSizeToFit: true,
        sortable: false,
        filter: false,
      }
    ];
  }, [reconciliation?.status, t]);

  if (loading) return <div className="p-4">{t('loading')}</div>;
  if (!reconciliation) return <div className="p-4">{t('notFound')}</div>;

  const isPosted = reconciliation.status === 'posted';
  const formatCurrency = (val: number) => new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(val);

  return (
    <div className="h-full flex flex-col bg-white">
      {/* GLOBAL HEADER (Outside of specific views) */}
      <div className="flex flex-col bg-white border-b border-gray-200 px-6 py-4 gap-4 shrink-0 z-10 shadow-sm relative">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => router.back()} 
              className="btn btn-secondary btn-sm"
              aria-label="Go back"
              title={t('tooltips.back')}
            >
              ΓåÉ
            </button>
            <h1 className="text-xl font-bold text-gray-900 tracking-tight">
              {t('reconciliationLabel', { account: reconciliation.accountName })}
            </h1>
            <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider border ${
              isPosted 
                ? 'bg-emerald-50 text-[var(--success)] border-emerald-200' 
                : 'bg-amber-50 text-[var(--warning)] border-amber-200'
            }`}>
              {isPosted ? tCommon('states.posted') : tCommon('states.draft')}
            </span>
            <span className="text-sm text-gray-500 font-medium ml-2">
              {t('statementDateLabel', { date: reconciliation.statementDate })}
            </span>
            
            <div className="flex bg-gray-100 p-1 rounded-lg ml-6 items-center">
              <button 
                onClick={() => setViewMode('bank')} 
                className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'bank' ? 'bg-white shadow-sm text-[var(--accent)]' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Bank Statement Match
              </button>
              <button 
                onClick={() => setViewMode('ledger')} 
                className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${viewMode === 'ledger' ? 'bg-white shadow-sm text-[var(--accent)]' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Ledger Lines
              </button>
            </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {!isPosted && (
              <>
                <button
                  onClick={handleDiscard}
                  disabled={posting}
                  className="btn btn-secondary disabled:opacity-50 disabled:cursor-not-allowed font-semibold"
                >
                  {t('discard')}
                </button>
                <button
                  onClick={handlePost}
                  disabled={posting || Math.abs(reconciliation.variance) > 0.001}
                  className="px-5 py-2 text-sm font-bold rounded-lg transition-all bg-[var(--accent)] text-white hover:brightness-110 shadow-sm whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed"
                  title={Math.abs(reconciliation.variance) > 0.001 ? t('varianceMustBeZero') : ''}
                >
                  {posting ? t('posting') : t('postReconciliation')}
                </button>
              </>
            )}
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4">
          <div className="p-3 bg-gray-50 rounded-lg border border-gray-200 shadow-sm">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-bold">{t('openingBalance')}</div>
            <div className="text-xl font-bold mt-0.5 text-gray-900">
              {formatCurrency(reconciliation.openingBalance)}
            </div>
          </div>
          <div className="p-3 bg-gray-50 rounded-lg border border-gray-200 shadow-sm">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-bold">{t('clearedBalance')}</div>
            <div className="text-xl font-bold mt-0.5 text-gray-900">
              {formatCurrency(reconciliation.clearedBalance)}
            </div>
          </div>
          <div className="p-3 bg-gray-50 rounded-lg border border-gray-200 shadow-sm">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-bold">{t('statementBalance')}</div>
            <div className="text-xl font-bold mt-0.5 text-gray-900">
              {formatCurrency(reconciliation.statementBalance)}
            </div>
          </div>
          <div className={`p-3 rounded-lg border shadow-sm transition-colors ${Math.abs(reconciliation.variance) < 0.001 ? 'bg-[#f0f8f6] border-[#006b5c]/30' : 'bg-red-50 border-red-200'}`}>
            <div className={`text-[10px] uppercase tracking-wider font-bold ${Math.abs(reconciliation.variance) < 0.001 ? 'text-[#006b5c]' : 'text-[var(--danger)]'}`}>
              {t('variance')}
            </div>
            <div className={`text-xl font-bold mt-0.5 ${Math.abs(reconciliation.variance) < 0.001 ? 'text-[#006b5c]' : 'text-[var(--danger)]'}`}>
              {formatCurrency(reconciliation.variance)}
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 min-h-0 flex flex-col bg-gray-50 relative">
        {viewMode === 'bank' ? (
          <BankMatchingView reconciliation={reconciliation} onUpdate={() => { fetchDetails(); setRefreshKey(k => k + 1); }} />
        ) : (
          <DataGrid
            refreshTrigger={refreshKey}
            endpoint={`/api/gl/reconciliations/${id}/unreconciled`}
            columns={columns}
            rowIdField="journalLineId"
            fetchAll={true}
            rowSelection="single"
            onSelectionChanged={(rows) => setSelectedRow(rows[0] || null)}
            context={{ handleToggle, isPosted }}
            renderHeader={({ searchInput, optionsButton, rowCount, loading: gridLoading }) => (
              <div className="flex flex-col bg-white border-b border-gray-200">
                <div className="flex flex-col px-6 py-3">
                  <div className="flex items-center gap-4">
                    <div className="flex items-center bg-[#f0f8f6] rounded px-2 py-0.5 mr-2">
                      <span className="text-[10px] font-bold text-[#006b5c] uppercase tracking-wider mr-1.5">{t('rows')}</span>
                      <span className="text-[11px] font-bold text-[#006b5c]">
                        {gridLoading ? '...' : rowCount.toLocaleString()}
                      </span>
                    </div>
                    <div className="flex-1 max-w-sm">
                      {searchInput}
                    </div>
                    {!isPosted && (
                      <>
                        <button
                          onClick={() => setAdjustmentModalOpen(true)}
                          className="btn btn-secondary btn-sm flex items-center gap-2 font-semibold"
                        >
                          {/* eslint-disable-next-line i18next/no-literal-string */}
                          <span className="material-symbols-outlined text-[18px]">add</span>
                          {t('quickAdjustment')}
                        </button>
                        <button
                          onClick={() => setSplitModalOpen(true)}
                          disabled={!selectedRow || selectedRow.isCleared}
                          className="btn btn-secondary btn-sm flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed font-semibold"
                          title={!selectedRow ? t('tooltips.selectRowToSplit') : selectedRow.isCleared ? t('tooltips.splitRowDisabled') : ''}
                        >
                          {/* eslint-disable-next-line i18next/no-literal-string */}
                          <span className="material-symbols-outlined text-[18px]">call_split</span>
                          {t('splitEntry')}
                        </button>
                      </>
                    )}
                    {optionsButton}
                  </div>
                </div>
              </div>
            )}
          />
        )}
      </div>
      <QuickAdjustmentModal 
        isOpen={isAdjustmentModalOpen} 
        onClose={() => setAdjustmentModalOpen(false)} 
        reconciliationId={id} 
        onSuccess={() => {
          fetchDetails();
          setRefreshKey(k => k + 1);
        }}
      />
      <SplitEntryModal
        isOpen={isSplitModalOpen}
        onClose={() => setSplitModalOpen(false)}
        reconciliationId={id}
        selectedLine={selectedRow}
        onSuccess={() => {
          fetchDetails();
          setRefreshKey(k => k + 1);
          setSelectedRow(null); // Clear selection after split
        }}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { getToken } from '@/lib/api';
import * as api from '@modbm/sdk';

function getExcelColumnName(colIndex: string): string {
  const num = parseInt(colIndex, 10);
  if (isNaN(num) || num.toString() !== colIndex) return colIndex;
  
  let temp = num;
  let letter = '';
  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }
  return letter;
}

interface BankImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export default function BankImportModal({ isOpen, onClose, onSuccess }: BankImportModalProps) {
  const t = useTranslations('gl.reconciliations');
  const [step, setStep] = useState(1);
  const [file, setFile] = useState<File | null>(null);
  const [glAccountId, setGlAccountId] = useState('');
  const [bankAccounts, setBankAccounts] = useState<any[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [profiles, setProfiles] = useState<any[]>([]);
  const [selectedProfileId, setSelectedProfileId] = useState('');
  
  // profile mapping state
  const [name, setName] = useState('');
  const [dateColumn, setDateColumn] = useState('');
  const [amountColumn, setAmountColumn] = useState('');
  const [descriptionColumn, setDescriptionColumn] = useState('');
  const [referenceColumn, setReferenceColumn] = useState('');
  const [headerRows, setHeaderRows] = useState(1);
  
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<{ autoMatchedCount: number, unmatchedCount: number } | null>(null);

  useEffect(() => {
    if (isOpen) {
      // fetch bank accounts
      api.glControllerGetAccounts({ isBankAccount: 'true' })
        .then(res => setBankAccounts(Array.isArray(res.data) ? res.data : (res.data as any).items || []))
        .catch(console.error);
    } else {
      // reset state when closed
      setStep(1);
      setFile(null);
      setResults(null);
      setSelectedProfileId('');
    }
  }, [isOpen]);

  useEffect(() => {
    if (glAccountId) {
      api.bankFeedsControllerGetProfiles(glAccountId).then(res => setProfiles(res.data)).catch(console.error);
    }
  }, [glAccountId]);

  if (!isOpen) return null;

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleParse = async () => {
    if (!file || !glAccountId) return;
    setLoading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      
      const res = await fetch('/api/gl/bank-feeds/parse', {
        method: 'POST',
        headers: { Authorization: `Bearer ${getToken()}` },
        body: formData,
      });
      
      if (!res.ok) throw new Error('Failed to parse CSV');
      const data = await res.json();
      setHeaders(Object.keys(data.headers));
      setStep(2);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleImport = async () => {
    setLoading(true);
    try {
      let finalProfileId = selectedProfileId;
      if (!selectedProfileId) {
        // create new profile
        const profileRes = await api.bankFeedsControllerCreateProfile({
          glAccountId,
          name: name || 'New Profile',
          dateColumn,
          amountColumn,
          descriptionColumn,
          referenceColumn: referenceColumn || undefined,
          headerRows
        });
        finalProfileId = profileRes.data.profileId;
      }

      const formData = new FormData();
      formData.append('file', file as File);
      formData.append('glAccountId', glAccountId);
      formData.append('profileId', finalProfileId);
      
      const res = await fetch('/api/gl/bank-feeds/import', {
        method: 'POST',
        headers: { Authorization: `Bearer ${getToken()}` },
        body: formData,
      });

      if (!res.ok) throw new Error('Failed to import CSV');
      const data = await res.json();

      setResults(data);
      setStep(3);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
      <div className="bg-[var(--bg-card)] rounded-lg shadow-xl w-full max-w-2xl border border-[var(--border)] overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-[var(--border)] bg-[var(--bg-secondary)] flex justify-between items-center shrink-0">
          <h2 className="text-xl font-bold text-[var(--text-primary)]">Import Bank Statement</h2>
          <button onClick={onClose} className="text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors">Γ£ò</button>
        </div>
        
        <div className="p-6 overflow-y-auto flex-1 text-[var(--text-primary)]">
          {step === 1 && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Bank Account</label>
                <select className="input w-full" value={glAccountId} onChange={e => setGlAccountId(e.target.value)}>
                  <option value="">Select an account...</option>
                  {bankAccounts.map(a => <option key={a.glAccountId} value={a.glAccountId}>{a.accountCode} - {a.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">CSV File</label>
                <div className="flex items-center gap-4">
                  <button type="button" className="btn btn-secondary" onClick={() => document.getElementById('csv-upload')?.click()}>
                    Choose File
                  </button>
                  <span className="text-sm text-[var(--text-muted)]">{file ? file.name : 'No file selected'}</span>
                  <input id="csv-upload" type="file" accept=".csv" onChange={handleFileUpload} className="hidden" />
                </div>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4">
              {profiles.length > 0 && (
                <div>
                  <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Saved Profile</label>
                  <select className="input w-full" value={selectedProfileId} onChange={e => setSelectedProfileId(e.target.value)}>
                    <option value="">Create new profile...</option>
                    {profiles.map(p => <option key={p.profileId} value={p.profileId}>{p.name}</option>)}
                  </select>
                </div>
              )}

              {!selectedProfileId && (
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Profile Name</label>
                    <input type="text" value={name} onChange={e => setName(e.target.value)} className="input w-full" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Date Column</label>
                    <select className="input w-full" value={dateColumn} onChange={e => setDateColumn(e.target.value)}>
                      <option value="">Select...</option>
                      {headers.map(h => <option key={h} value={h}>{getExcelColumnName(h)}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Amount Column</label>
                    <select className="input w-full" value={amountColumn} onChange={e => setAmountColumn(e.target.value)}>
                      <option value="">Select...</option>
                      {headers.map(h => <option key={h} value={h}>{getExcelColumnName(h)}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Description Column</label>
                    <select className="input w-full" value={descriptionColumn} onChange={e => setDescriptionColumn(e.target.value)}>
                      <option value="">Select...</option>
                      {headers.map(h => <option key={h} value={h}>{getExcelColumnName(h)}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Reference Column (Optional)</label>
                    <select className="input w-full" value={referenceColumn} onChange={e => setReferenceColumn(e.target.value)}>
                      <option value="">None</option>
                      {headers.map(h => <option key={h} value={h}>{getExcelColumnName(h)}</option>)}
                    </select>
                  </div>
                </div>
              )}
            </div>
          )}

          {step === 3 && results && (
            <div className="space-y-4 text-center py-6">
              <div className="flex justify-center items-center gap-2 mb-2">
                <span className="material-symbols-outlined text-[24px] text-[var(--success)]">check_circle</span>
                <h3 className="text-lg font-bold text-[var(--text-primary)]">Import complete</h3>
              </div>
              <div className="text-[var(--text-muted)]">
                <p>{results.autoMatchedCount} lines were auto-reconciled by rules.</p>
                <p>{results.unmatchedCount} lines were queued for manual reconciliation.</p>
              </div>
            </div>
          )}
        </div>

        <div className="px-6 py-4 border-t border-[var(--border)] bg-[var(--bg-secondary)] flex justify-end gap-3 shrink-0">
          {step < 3 && (
            <button onClick={onClose} className="btn btn-secondary">
              Cancel
            </button>
          )}
          
          {step === 1 && (
            <button onClick={handleParse} disabled={!file || !glAccountId || loading} className="btn btn-primary">
              {loading ? 'Parsing...' : 'Next'}
            </button>
          )}

          {step === 2 && (
            <button onClick={handleImport} disabled={loading} className="btn btn-primary">
              {loading ? 'Importing...' : 'Import'}
            </button>
          )}

          {step === 3 && (
            <button onClick={() => { onClose(); onSuccess(); }} className="btn btn-primary">
              Done
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import React, { useMemo } from 'react';
import { useRouter } from 'next/navigation';
import DataGrid from '@/components/DataGrid';
import type { ColDef } from 'ag-grid-community';
import { useTranslations } from 'next-intl';
import BankImportModal from './components/BankImportModal';

export default function ReconciliationsPage() {
  const t = useTranslations('gl.reconciliations');
  const tCommon = useTranslations('common');
  useDocumentTitle(t('title'));
  const router = useRouter();
  const [isImportModalOpen, setIsImportModalOpen] = React.useState(false);

  const columns = useMemo<ColDef[]>(() => [
    { field: 'statementDate', headerName: t('columns.statementDate'), width: 140 },
    { field: 'accountName', headerName: t('columns.customer'), flex: 1 },
    { 
      field: 'statementBalance', 
      headerName: t('columns.statementBalance'), 
      width: 180,
      valueFormatter: (params) => {
        if (params.value == null) return '';
        return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(params.value);
      }
    },
    { 
      field: 'status', 
      headerName: t('columns.status'), 
      width: 120,
      cellRenderer: (params: any) => {
        if (!params.value) return '';
        const isPosted = params.value === 'posted';
        return (
          <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium border ${
            isPosted 
              ? 'bg-emerald-50 text-[var(--success)] border-emerald-200' 
              : 'bg-amber-50 text-[var(--warning)] border-amber-200'
          }`}>
            {isPosted ? tCommon('states.posted') : tCommon('states.draft')}
          </span>
        );
      }
    }
  ], [t, tCommon]);

  return (
    <div className="h-full flex flex-col bg-white">
      <div className="flex-1 min-h-0 flex flex-col">
        <DataGrid
          endpoint="/api/gl/reconciliations"
          columns={columns}
          fetchAll={true}
          onRowClicked={(row: any) => router.push(`/general-ledger/reconciliations/${row.reconciliationId}`)}
          renderHeader={({ searchInput, optionsButton, rowCount, loading }) => (
            <div className="flex flex-col bg-white border-b border-gray-200">
              <div className="flex items-center px-6 py-4 gap-6">
                <div className="flex items-center gap-3 shrink-0">
                  <h1 className="text-xl font-bold text-gray-900 tracking-tight">{t('title')}</h1>
                  <div className="flex items-center bg-[#f0f8f6] rounded px-2 py-0.5 mt-0.5">
                    <span className="text-[10px] font-bold text-[#006b5c] uppercase tracking-wider mr-1.5">{t('rows')}</span>
                    <span className="text-[11px] font-bold text-[#006b5c]">
                      {loading ? '...' : rowCount.toLocaleString()}
                    </span>
                  </div>
                </div>
                
                <div className="flex-1">
                  {searchInput}
                </div>

                <div className="flex items-center gap-3 shrink-0">
                  {optionsButton}
                  <button
                    onClick={() => setIsImportModalOpen(true)}
                    className="btn btn-secondary"
                  >
                    Import Statement
                  </button>
                  <button
                    onClick={() => router.push('/general-ledger/reconciliations/new')}
                    className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110 shadow-sm whitespace-nowrap"
                  >
                    + {t('newReconciliation')}
                  </button>
                </div>
              </div>
            </div>
          )}
        />
      </div>
      <BankImportModal 
        isOpen={isImportModalOpen} 
        onClose={() => setIsImportModalOpen(false)} 
        onSuccess={() => setIsImportModalOpen(false)} 
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import * as api from '@modbm/sdk';

export default function RulesEnginePage() {
  const t = useTranslations('gl.reconciliations');
  useDocumentTitle('Reconciliation Rules');

  const [rules, setRules] = useState<any[]>([]);
  const [glAccounts, setGlAccounts] = useState<any[]>([]);
  
  // new rule state
  const [bankAccountId, setBankAccountId] = useState('');
  const [conditionType, setConditionType] = useState('contains');
  const [conditionValue, setConditionValue] = useState('');
  const [targetGlAccountId, setTargetGlAccountId] = useState('');
  
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const accs = await api.glControllerGetAccounts();
      setGlAccounts((accs as any).data?.items || []);
      const r = await api.bankFeedsControllerGetRules();
      setRules((r as any).data || []);
    } catch (err) {
      console.error(err);
    }
  };

  const handleCreate = async () => {
    if (!conditionValue || !targetGlAccountId) return;
    setLoading(true);
    try {
      await api.bankFeedsControllerCreateRule({
        glAccountId: bankAccountId || undefined,
        conditionType,
        conditionValue,
        targetGlAccountId,
        priority: 10
      });
      setConditionValue('');
      setTargetGlAccountId('');
      await loadData();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const bankAccs = glAccounts.filter(a => a.isBankAccount);

  return (
    <div className="h-full flex flex-col bg-[var(--bg-primary)] p-6 overflow-y-auto">
      <div className="max-w-4xl w-full mx-auto space-y-6">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Reconciliation Rules</h1>
        </div>

        <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg p-6 shadow-sm">
          <h2 className="text-lg font-bold text-[var(--text-primary)] mb-4">Create New Rule</h2>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Bank Account (Optional)</label>
              <select 
                className="w-full p-2 bg-[var(--bg-primary)] border border-[var(--border)] rounded text-[var(--text-primary)]"
                value={bankAccountId}
                onChange={e => setBankAccountId(e.target.value)}
              >
                <option value="">All Bank Accounts</option>
                {bankAccs.map(a => <option key={a.glAccountId} value={a.glAccountId}>{a.accountCode} - {a.name}</option>)}
              </select>
            </div>
            
            <div>
              <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Target GL Account (Tag to)</label>
              <select 
                className="w-full p-2 bg-[var(--bg-primary)] border border-[var(--border)] rounded text-[var(--text-primary)]"
                value={targetGlAccountId}
                onChange={e => setTargetGlAccountId(e.target.value)}
              >
                <option value="">Select Account...</option>
                {glAccounts.map(a => <option key={a.glAccountId} value={a.glAccountId}>{a.accountCode} - {a.name}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Condition Type</label>
              <select 
                className="w-full p-2 bg-[var(--bg-primary)] border border-[var(--border)] rounded text-[var(--text-primary)]"
                value={conditionType}
                onChange={e => setConditionType(e.target.value)}
              >
                <option value="contains">Description Contains</option>
                <option value="starts_with">Description Starts With</option>
                <option value="exact_match">Description Exact Match</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--text-muted)] mb-1">Condition Value</label>
              <input 
                type="text" 
                placeholder="e.g. STRIPE PAYOUT"
                className="w-full p-2 bg-[var(--bg-primary)] border border-[var(--border)] rounded text-[var(--text-primary)]"
                value={conditionValue}
                onChange={e => setConditionValue(e.target.value)}
              />
            </div>
          </div>
          
          <div className="mt-4 flex justify-end">
            <button 
              onClick={handleCreate}
              disabled={loading || !conditionValue || !targetGlAccountId}
              className="px-4 py-2 bg-[var(--accent)] text-white font-bold rounded hover:brightness-110 disabled:opacity-50"
            >
              Add Rule
            </button>
          </div>
        </div>

        <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-lg overflow-hidden shadow-sm">
          <table className="w-full text-left">
            <thead className="bg-[var(--bg-secondary)] border-b border-[var(--border)] text-[var(--text-muted)] text-sm">
              <tr>
                <th className="px-4 py-3 font-medium">Bank Account</th>
                <th className="px-4 py-3 font-medium">Condition</th>
                <th className="px-4 py-3 font-medium">Target GL</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--border)]">
              {rules.map(rule => {
                const bank = bankAccs.find(a => a.glAccountId === rule.glAccountId);
                const target = glAccounts.find(a => a.glAccountId === rule.targetGlAccountId);
                return (
                  <tr key={rule.ruleId} className="hover:bg-[var(--bg-primary)] transition-colors text-[var(--text-primary)]">
                    <td className="px-4 py-3">{bank ? bank.name : 'All Accounts'}</td>
                    <td className="px-4 py-3">
                      <span className="bg-[var(--bg-secondary)] border border-[var(--border)] px-2 py-0.5 rounded text-xs mr-2">
                        {rule.conditionType}
                      </span>
                      {rule.conditionValue}
                    </td>
                    <td className="px-4 py-3 font-medium text-[var(--brand-blue)]">
                      {target ? `${target.accountCode} - ${target.name}` : rule.targetGlAccountId}
                    </td>
                  </tr>
                );
              })}
              {rules.length === 0 && (
                <tr>
                  <td colSpan={3} className="px-4 py-8 text-center text-[var(--text-muted)]">
                    No rules defined yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import Link from 'next/link';

interface LedgerEntrySlideOverProps {
  entryId: string | null;
  onClose: () => void;
}

interface EntryDetails {
  entryId: string;
  entryNumber: string;
  sourceType: string;
  entryDate: string;
  memo: string | null;
  createdBy: string | null;
  relatedDocument: { number: string; link?: string } | null;
  relatedParty: { name: string; number: string; link?: string } | null;
  lines: Array<{
    ledgerId: string;
    productNumber: string;
    productName: string;
    change: string;
    locationName: string;
    binCode: string;
  }>;
}

export default function LedgerEntrySlideOver({ entryId, onClose }: LedgerEntrySlideOverProps) {
  const t = useTranslations('inventory.ledger');
  const tCommon = useTranslations('common');
  
  const [loading, setLoading] = useState(false);
  const [details, setDetails] = useState<EntryDetails | null>(null);

  useEffect(() => {
    if (!entryId) {
      setDetails(null);
      return;
    }

    setLoading(true);
    api.inventoryControllerGetEntryDetails(entryId)
      .then(res => setDetails(res.data as unknown as EntryDetails))
      .catch((err) => reportError(err, 'LedgerEntrySlideOver'))
      .finally(() => setLoading(false));
  }, [entryId]);

  return (
    <SlideOver
      isOpen={!!entryId}
      onClose={onClose}
      title={details ? `${details.sourceType}: ${details.entryNumber}` : t('title')}
      subtitle={details ? `${new Date(details.entryDate).toLocaleString()} ┬╖ ${details.createdBy || t('system')}` : undefined}
      width="max-w-2xl"
    >
      {loading ? (
        <div className="flex justify-center items-center py-12">
          {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="loading loading-spinner text-gray-400"></span>
        </div>
      ) : details ? (
        <div className="space-y-6">
          <div className="card space-y-5">
            <div className="flex flex-col gap-5 text-sm">
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('sourceType')}</span>
                <span className="text-[#041627]">{details.sourceType}</span>
              </div>
              {details.relatedDocument && (
                <div>
                  <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('sourceDocument')}</span>
                  {details.relatedDocument.link ? (
                    <Link href={details.relatedDocument.link} className="text-[var(--accent)] hover:underline" onClick={onClose}>
                      {details.relatedDocument.number}
                    </Link>
                  ) : (
                    <span className="text-[#041627] font-semibold">{details.relatedDocument.number}</span>
                  )}
                </div>
              )}
              {details.relatedParty && (
                <div>
                  <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('relatedParty')}</span>
                  <div className="text-[#041627]">
                    {details.relatedParty.link ? (
                      <Link href={details.relatedParty.link} className="text-[var(--accent)] hover:underline" onClick={onClose}>
                        {details.relatedParty.name}
                      </Link>
                    ) : (
                      <span className="font-semibold">{details.relatedParty.name}</span>
                    )}
                  </div>
                </div>
              )}
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('operationMemo')}</span>
                <span className="text-[#041627]">{details.memo || 'ΓÇö'}</span>
              </div>
            </div>
          </div>

          <div className="rounded-xl border border-gray-200 overflow-hidden bg-white">
            <table className="w-full text-sm text-left">
              <thead className="bg-[#f8f9fa] border-b border-gray-200 text-[#041627] font-semibold text-xs uppercase tracking-wider">
                <tr>
                  <th className="px-5 py-3">{t('columns.product')}</th>
                  <th className="px-5 py-3">{t('columns.locationBin')}</th>
                  <th className="px-5 py-3 text-right">{t('columns.qtyChange')}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {details.lines.map((l) => {
                  const val = parseFloat(l.change || '0');
                  const isPositive = val > 0;
                  const isNegative = val < 0;
                  
                  return (
                    <tr key={l.ledgerId} className="hover:bg-gray-50/50 transition-colors">
                      <td className="px-5 py-3 align-top">
                        <div className="font-bold text-[#041627]">{l.productNumber}</div>
                        <div className="text-gray-500 text-xs mt-0.5 max-w-[280px] break-words leading-tight">{l.productName}</div>
                      </td>
                      <td className="px-5 py-3 align-top whitespace-nowrap">
                        <div className="font-semibold text-gray-700">{l.locationName}</div>
                        <div className="font-mono text-xs text-gray-500 mt-0.5">{l.binCode}</div>
                      </td>
                      <td className={`px-5 py-3 align-top text-right font-mono font-bold ${isPositive ? 'text-[#006b5c]' : isNegative ? 'text-[#b45309]' : 'text-gray-600'}`}>
                        {isPositive ? `+${val.toLocaleString()}` : val.toLocaleString()}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {details.lines.length === 0 && (
              <div className="p-8 text-center text-gray-500 text-sm">
                {t('noLines')}
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="py-12 text-center text-gray-500">
          {t('loadFailed')}
        </div>
      )}
    </SlideOver>
  );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import MasterDetailLayout from '@/components/shared/MasterDetailLayout';

import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useSettings } from '@/components/SettingsProvider';
import { SALES_ORDER_PICK_STATE } from '@modbm/shared';
import { getErrorMessage } from '@modbm/shared';

interface UnifiedOrder {
    id: string;
    orderNumber: string;
    name: string;
    customerName: string;
    customerOrderNumber: string;
    stateCode: string;
    createdBy: string;
    createdOn: string | null;
    totalPrice: string | null;
    currencyCode: string | null;
    pickabilityStatus: 'ready' | 'partial' | 'blocked';
    hasAllocation?: boolean;
    type?: 'sales_order' | 'transfer_order';
}

interface PickAllocation {
    pickId: string;
    salesOrderId: string;
    salesOrderLineId: string;
    productId: string;
    binId: string;
    quantity: string;
    stateCode: string;
    binName?: string;
    line?: PickingLine;
}

interface PickingLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productType: string;
    productDescription: string;
    locationName: string;
    availableBins: { binId: string; binName: string; onHand: string }[];
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    remaining: string;
    isFullyPicked: boolean;
    isPhysical: boolean;
    onHand: string;
    hasAllocation?: boolean;
}

interface PickingSummary {
    totalLines: number;
    fullyPickedLines: number;
    isFullyPicked: boolean;
    lines: PickingLine[];
    picks: PickAllocation[];
}

export default function PickingPage() {
    const t = useTranslations('picking');
    const tCommon = useTranslations('common');
    useDocumentTitle(t('title'));
    const { app } = useSettings();

    const [locations, setLocations] = useState<{ locationId: string; code: string; name: string }[]>([]);
    const [selectedLocationId, setSelectedLocationId] = useState<string>('');
    const [pendingOrders, setPendingOrders] = useState<UnifiedOrder[]>([]);
    const [selectedOrder, setSelectedOrder] = useState<UnifiedOrder | null>(null);
    const [loadingOrders, setLoadingOrders] = useState(false);
    const [activeTab, setActiveTab] = useState<'ready' | 'partial' | 'blocked'>('ready');
    
    // Picking Context
    const [pickingSummary, setPickingSummary] = useState<PickingSummary | null>(null);
    const [loadingSummary, setLoadingSummary] = useState(false);
    
    // Action State
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [pickInputs, setPickInputs] = useState<Record<string, { quantity: string, binId: string }>>({});

    // Fetch Locations
    useEffect(() => {
        api.inventoryControllerFindAllLocations().then((response) => {
                const res = response.data as any;
                const locs = Array.isArray(res) ? res : (res.data || []);
                setLocations(locs);
                if (locs.length > 0) {
                    const defaultLocId = app?.defaultFulfillmentLocationId || locs[0].locationId;
                    setSelectedLocationId(defaultLocId);
                }
            })
            .catch(err => reportError(err, 'Failed to load locations'));
    }, [app?.defaultFulfillmentLocationId]);

    // Fetch Pending Orders
    const loadOrders = useCallback(() => {
        setLoadingOrders(true);
        const params: any = {};
        if (selectedLocationId) params.locationId = selectedLocationId;

        api.orderPickingControllerGetPickingQueue(params)
            .then(data => {
                setPendingOrders(((data as any).data || data) as unknown as UnifiedOrder[]);
            })
            .catch(err => reportError(err, 'Failed to load pending orders'))
            .finally(() => setLoadingOrders(false));
    }, [selectedLocationId]);

    useEffect(() => {
        loadOrders();
    }, [loadOrders]);

    const filteredOrders = useMemo(() => {
        const filtered = pendingOrders.filter(o => o.pickabilityStatus === activeTab);
        // Allocated orders sort first
        filtered.sort((a, b) => {
            if (a.hasAllocation !== b.hasAllocation) return a.hasAllocation ? -1 : 1;
            return 0;
        });
        return filtered;
    }, [pendingOrders, activeTab]);

    // Fetch Summary for Selected Order
    const loadSummary = useCallback(() => {
        if (!selectedOrder) {
            setPickingSummary(null);
            return;
        }

        setLoadingSummary(true);
        setError(null);
        
        const summaryPromise = selectedOrder.type === 'transfer_order' 
            ? api.transfersControllerGetPickingSummary(selectedOrder.id) 
            : api.orderPickingControllerGetPickingSummary(selectedOrder.id);
            
        summaryPromise
            .then((res) => {
                const data = res.data;
                setPickingSummary(data as unknown as PickingSummary);
                
                // Initialize default quantities (what's remaining and fits in a bin)
                const defaultInputs: Record<string, { quantity: string, binId: string }> = {};
                ((data as any).lines || []).forEach((line: PickingLine) => {
                    if (line.isPhysical && !line.isFullyPicked && parseFloat(line.remaining) > 0) {
                        const bestBin = line.availableBins[0];
                        if (bestBin) {
                            const remaining = parseFloat(line.remaining);
                            const onHand = parseFloat(bestBin.onHand);
                            const take = Math.min(remaining, onHand);
                            if (take > 0) {
                                defaultInputs[line.salesOrderLineId] = {
                                    quantity: String(take),
                                    binId: bestBin.binId
                                };
                            }
                        }
                    }
                });
                setPickInputs(defaultInputs);
            })
            .catch(err => setError(getErrorMessage(err)))
            .finally(() => setLoadingSummary(false));
    }, [selectedOrder]);

    useEffect(() => {
        loadSummary();
    }, [loadSummary]);

    const handlePickLine = async (lineId: string) => {
        if (!selectedOrder) return;
        
        const input = pickInputs[lineId];
        if (!input || !input.quantity || !input.binId) return;

        setIsSubmitting(true);
        setError(null);

        try {
            if (selectedOrder.type === 'transfer_order') {
                await api.transfersControllerPickLine(selectedOrder.id, lineId, { quantity: input.quantity, binId: input.binId });
            } else {
                await api.orderPickingControllerPickLine(selectedOrder.id, lineId, { quantity: input.quantity, binId: input.binId });
            }
            await loadSummary();
        } catch (err: unknown) {
            setError(getErrorMessage(err));
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleCancelPick = async (pickId: string) => {
        if (!selectedOrder) return;
        setIsSubmitting(true);
        setError(null);
        try {
            if (selectedOrder.type === 'transfer_order') {
                await api.transfersControllerCancelPick(selectedOrder.id, pickId);
            } else {
                await api.orderPickingControllerCancelPick(selectedOrder.id, pickId);
            }
            await loadSummary();
        } catch (err: unknown) {
            setError(getErrorMessage(err));
        } finally {
            setIsSubmitting(false);
        }
    };

    const handlePrintDocket = async () => {
        if (!selectedOrder) return;
        setIsGeneratingPdf(true);
        try {
            const response = await api.reportsControllerRunHook('picking-slip', { shipmentId: selectedOrder.id }, { id: selectedOrder.id, context: 'picking-slip' });
            const blob = response.data as Blob;
            const url = window.URL.createObjectURL(blob);
            window.open(url, '_blank');
        } catch (err: unknown) {
            alert('Failed to generate PDF: ' + getErrorMessage(err));
        } finally {
            setIsGeneratingPdf(false);
        }
    };

    const { itemsToPick, unavailableItems, pickedItems, shippedItems } = useMemo(() => {
        if (!pickingSummary) return { itemsToPick: [], unavailableItems: [], pickedItems: [], shippedItems: [] };
        
        const toPick = pickingSummary.lines.filter(l => parseFloat(l.remaining) > 0 && parseFloat(l.onHand) > 0 && l.isPhysical);
        const unavailable = pickingSummary.lines.filter(l => parseFloat(l.remaining) > 0 && parseFloat(l.onHand) <= 0 && l.isPhysical);
        
        const picked = pickingSummary.picks.filter(p => p.stateCode === SALES_ORDER_PICK_STATE.PICKED).map(p => {
            const line = pickingSummary.lines.find(l => l.salesOrderLineId === p.salesOrderLineId);
            return { ...p, line };
        });
        
        const shipped = pickingSummary.picks.filter(p => p.stateCode === SALES_ORDER_PICK_STATE.SHIPPED).map(p => {
            const line = pickingSummary.lines.find(l => l.salesOrderLineId === p.salesOrderLineId);
            return { ...p, line };
        });

        return { itemsToPick: toPick, unavailableItems: unavailable, pickedItems: picked, shippedItems: shipped };
    }, [pickingSummary]);

    return (
        <MasterDetailLayout
            title={t('title')}
            controls={
                <>
                    <span className="text-sm font-semibold text-[var(--text-muted)] hidden sm:inline">{t('locationLabel')}</span>
                    <select
                        value={selectedLocationId}
                        onChange={(e) => setSelectedLocationId(e.target.value)}
                        className="input text-sm w-full sm:w-48"
                    >
                        {locations.map(loc => (
                            <option key={loc.locationId} value={loc.locationId}>
