'use client';

import { useState, useEffect } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import LocationSelect from '@/components/shared/LocationSelect';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { getErrorMessage } from '@modbm/shared';

interface LineItem {
  productId: string;
  productNumber: string;
  name: string;
  quantity: number;
}

interface CreateTransferSlideOverProps {
  open: boolean;
  onClose: () => void;
  onCreated: () => void;
}

export default function CreateTransferSlideOver({ open, onClose, onCreated }: CreateTransferSlideOverProps) {
  const t = useTranslations('transfers');
  const tCommon = useTranslations('common');
  
  const [sourceLocationId, setSourceLocationId] = useState('');
  const [destinationLocationId, setDestinationLocationId] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<LineItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (open) {
      // Reset state
      setSourceLocationId('');
      setDestinationLocationId('');
      setNotes('');
      setLines([]);
    }
  }, [open]);

  const handleAddProduct = (product: any) => {
    // Check if product already exists
    const existingIndex = lines.findIndex(l => l.productId === product.productId);
    if (existingIndex >= 0) {
      updateLine(existingIndex, 'quantity', lines[existingIndex].quantity + 1);
    } else {
      setLines([...lines, { 
        productId: product.productId, 
        productNumber: product.productNumber,
        name: product.name,
        quantity: 1 
      }]);
    }
  };

  const handleRemoveLine = (index: number) => {
    setLines(lines.filter((_, i) => i !== index));
  };

  const updateLine = (index: number, field: 'quantity', value: number) => {
    const newLines = [...lines];
    newLines[index] = { ...newLines[index], [field]: value };
    setLines(newLines);
  };

  const handleSubmit = async () => {
    if (!sourceLocationId || !destinationLocationId) {
      toast.error('Source and destination locations are required.');
      return;
    }
    
    if (sourceLocationId === destinationLocationId) {
      toast.error('Source and destination locations must be different.');
      return;
    }

    const validLines = lines
      .filter(l => l.productId && l.quantity > 0)
      .map(l => ({
        productId: l.productId,
        quantity: l.quantity.toString()
      }));
    
    try {
      setIsSubmitting(true);
      await api.transfersControllerCreate({
        sourceLocationId,
        destinationLocationId,
        notes,
        lines: validLines
      });
      onCreated();
      onClose();
    } catch (e: unknown) {
      toast.error(getErrorMessage(e) || 'Failed to create transfer order');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <SlideOver
      isOpen={open}
      onClose={onClose}
      title={t('createSlideOver.title')}
      subtitle={t('createSlideOver.subtitle')}
      width="max-w-3xl"
      footer={
        <div className="flex items-center justify-end gap-3 w-full">
          <button type="button" className="btn btn-ghost" onClick={onClose} disabled={isSubmitting}>
            {tCommon('cancel')}
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSubmitting || !sourceLocationId || !destinationLocationId}
            className="btn btn-primary bg-[#006b5c] hover:bg-[#005246] border-none text-white shadow-sm"
          >
            {isSubmitting ? (
              <><span className="loading loading-spinner loading-sm mr-2" />{tCommon('saving')}</>
            ) : (
              t('buttons.createTransfer')
            )}
          </button>
        </div>
      }
    >
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              {t('columns.sourceLocation')} *
            </label>
            <LocationSelect
              className="w-full"
              value={sourceLocationId}
              onChange={(val) => setSourceLocationId(val || '')}
              placeholder={t('placeholders.selectSourceLocation')}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              {t('columns.destinationLocation')} *
            </label>
            <LocationSelect
              className="w-full"
              value={destinationLocationId}
              onChange={(val) => setDestinationLocationId(val || '')}
              placeholder={t('placeholders.selectDestinationLocation')}
              required
            />
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            {t('columns.notes')}
          </label>
          <textarea
            className="input w-full"
            rows={3}
            placeholder={t('placeholders.notes')}
            value={notes}
            onChange={e => setNotes(e.target.value)}
          />
        </div>

        <div className="border-t border-gray-200 pt-6">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-medium text-lg">{t('lineItems')}</h4>
            <ProductSearchInput
              onSelect={handleAddProduct}
              placeholder="Search product..."
              style={{ width: 240 }}
              fulfillmentLocationId={sourceLocationId}
            />
          </div>

          <div className="space-y-3">
            {lines.map((line, index) => (
              <div key={index} className="flex gap-3 items-center">
                <div className="flex-1 text-sm">
                  <span className="font-semibold text-gray-900">{line.productNumber}</span>
                  <span className="text-gray-500 ml-2">{line.name}</span>
                </div>
                <div className="w-32">
                  <input
                    type="number"
                    min="1"
                    className="input w-full"
                    value={line.quantity || ''}
                    onChange={e => updateLine(index, 'quantity', parseFloat(e.target.value))}
                  />
                </div>
                <button
                  className="text-gray-400 hover:text-red-500"
                  onClick={() => handleRemoveLine(index)}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined">delete</span>
                  {/* eslint-enable i18next/no-literal-string */}
                </button>
              </div>
            ))}
            {lines.length === 0 && (
              <div className="text-sm text-gray-500 italic">{t('noLinesAdded')}</div>
            )}
          </div>
        </div>
      </div>
    </SlideOver>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import StateBadge from '@/components/StateBadge';
import ActivityTimeline from '@/components/shared/ActivityTimeline';
import { ValidState } from '@/types/states';
import { useTransferOrder } from './useTransferOrder';
import { TRANSFER_ORDER_STATE } from '@modbm/shared';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import { MobileCardField } from '@/components/shared/DataTable';

export default function TransferDetailsClient({ id }: { id: string }) {
  const router = useRouter();
  const tCommon = useTranslations('common');
  const tTransfers = useTranslations('transfers');

  const {
    order,
    loading,
    error,
    saving,
    clearError,
    editNotes,
    setEditNotes,
    saveHeader,
    addLine,
    updateLine,
    removeLine,
    shipOrder,
    cancelOrder,
  } = useTransferOrder(id);

  useDocumentTitle(order ? tTransfers('transferTitle', { number: order.orderNumber }) : null);

  if (loading) {
    return (
      <div className="flex items-center justify-center flex-1">
        <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
      </div>
    );
  }

  if (!order) {
    return (
      <div className="flex flex-col items-center justify-center flex-1">
        <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
          {error || tTransfers('notFound')}
        </p>
        <button className="btn btn-secondary" onClick={() => router.push('/inventory/transfers')}>
          {tTransfers('backToTransfers')}
        </button>
      </div>
    );
  }

  const isEditable = order.stateCode === TRANSFER_ORDER_STATE.CONFIRMED;
  const canCancel = [
    TRANSFER_ORDER_STATE.CONFIRMED,
    TRANSFER_ORDER_STATE.PICKING,
    TRANSFER_ORDER_STATE.SHIPPED,
  ].includes(order.stateCode );
  const headerDirty = order.notes !== editNotes;

  const handleCancel = async () => {
    if (window.confirm(tTransfers('cancelConfirm'))) {
      await cancelOrder();
    }
  };

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={order.orderNumber}
          subtitle={tTransfers('subtitleFlow', {
            source: order.sourceLocationName || order.sourceLocationId || '',
            destination: order.destinationLocationName || order.destinationLocationId || ''
          })}
          onBack={() => router.push('/inventory/transfers')}
          isSaving={saving}
          badges={<StateBadge state={order.stateCode as ValidState} />}
          actions={
            <div className="flex gap-2">
              {canCancel && (
                <button
                  className="btn btn-danger btn-sm"
                  onClick={handleCancel}
                  disabled={saving}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
                  {/* eslint-enable i18next/no-literal-string */}
                  {tCommon('cancel')}
                </button>
              )}
            </div>
          }
        />
      }
    >
      <div className="flex flex-col gap-3">
        {error && (
          <div
            className="px-4 py-3 rounded-lg text-sm"
            style={{
              background: 'rgba(239, 68, 68, 0.1)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              color: '#f87171',
            }}
          >
            {error}
            <button className="ml-3 text-xs underline" onClick={clearError}>{tCommon('dismiss')}</button>
          </div>
        )}

        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.sourceLocation')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {order.sourceLocationName || order.sourceLocationId}
              </p>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.destinationLocation')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {order.destinationLocationName || order.destinationLocationId}
              </p>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.createdOn')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {new Date(order.createdOn).toLocaleString()} {tCommon('by')} {order.createdBy}
              </p>
            </div>
            <div className="col-span-2">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.notes')}
              </label>
              <input
                className="input w-full"
                value={editNotes}
                onChange={(e) => setEditNotes(e.target.value)}
                onBlur={saveHeader}
                disabled={!isEditable}
                placeholder={tTransfers('placeholders.notes')}
              />
            </div>
          </div>
        </div>

        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">inventory_2</span>
              {/* eslint-enable i18next/no-literal-string */}
              {tTransfers('lineItems')}
            </h3>
            {isEditable && (
              <ProductSearchInput
                onSelect={(p: any) => addLine(p.productId, 1)}
                placeholder={tTransfers('placeholders.searchProduct')}
                style={{ width: 240 }}
              />
            )}
          </div>

          <div className="hidden lg:block overflow-x-auto w-full">
            <table className="table-lines">
            <thead>
              <tr>
                <th>{tTransfers('columns.product')}</th>
                <th>{tTransfers('columns.description')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.ordered')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.shipped')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.received')}</th>
                {isEditable && <th style={{ width: 50 }}></th>}
              </tr>
            </thead>
            <tbody>
              {order.lines?.map((line: any) => (
                <tr key={line.transferOrderLineId}>
                  <td style={{ fontWeight: 600, fontSize: 12 }}>
                    {line.productNumber || 'ΓÇö'}
                  </td>
                  <td>{line.productDescription || 'ΓÇö'}</td>
                  {isEditable ? (
                    <td style={{ textAlign: 'right' }}>
                      <input
                        className="input"
                        type="number"
                        min="1"
                        step="1"
                        style={{ width: '100%', textAlign: 'right' }}
                        defaultValue={line.quantity}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (val > 0 && val !== parseFloat(line.quantity)) {
                            updateLine(line.transferOrderLineId, val);
                          }
                        }}
                      />
                    </td>
                  ) : (
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                      {line.quantity}
                    </td>
                  )}
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {line.quantityShipped || 0}
                  </td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {line.quantityReceived || 0}
                  </td>
                  {isEditable && (
                    <td>
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => removeLine(line.transferOrderLineId)}
                        title={tTransfers('removeLine')}
                      >
                        <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                      </button>
                    </td>
                  )}
                </tr>
              ))}
              {(!order.lines || order.lines.length === 0) && (
                <tr>
                  <td
                    colSpan={isEditable ? 6 : 5}
                    style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}
                  >
                    {tTransfers('noLineItems')}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          </div>
          <div className="lg:hidden flex flex-col gap-3 w-full">
            {order.lines?.map((line: any, idx: number) => (
              <div key={line.transferOrderLineId} className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col shadow-sm">
                <div className="flex justify-between items-start gap-2 mb-2">
                  <div className="font-semibold text-sm text-[var(--accent)]">
                    {line.productNumber || 'ΓÇö'}
                  </div>
                  <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{idx + 1}</div>
                </div>
                <div className="text-sm text-slate-600 font-medium mb-3">
                  {line.productDescription || 'ΓÇö'}
                </div>
                <div className="flex flex-col gap-1 border-t border-slate-100 pt-2">
                  <MobileCardField label={tTransfers('columns.ordered')} value={
                    isEditable ? (
                      <input
                        className="input"
                        type="number"
                        min="1"
                        step="1"
                        style={{ width: '100px', textAlign: 'right', padding: '4px 8px', height: '32px' }}
                        defaultValue={line.quantity}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (val > 0 && val !== parseFloat(line.quantity)) {
                            updateLine(line.transferOrderLineId, val);
                          }
                        }}
                      />
                    ) : line.quantity
                  } />
                  <MobileCardField label={tTransfers('columns.shipped')} value={line.quantityShipped || 0} />
                  <MobileCardField label={tTransfers('columns.received')} value={line.quantityReceived || 0} />
                  {isEditable && (
                    <div className="flex justify-end pt-2 mt-1 border-t border-slate-50">
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => removeLine(line.transferOrderLineId)}
                        title={tTransfers('removeLine')}
                      >
                        <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} /> {tCommon('delete')}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {(!order.lines || order.lines.length === 0) && (
              <div className="text-center py-6 text-slate-400 text-sm">
                {tTransfers('noLineItems')}
              </div>
            )}
          </div>
        </div>

        {/* Activity Timeline */}
        <div className="card">
          <ActivityTimeline events={order.events || []} />
        </div>
      </div>
    </DetailsLayout>
  );
}

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import DataGrid from '@/components/DataGrid';
import { KitComponentSlideOver } from './KitComponentSlideOver';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { getErrorMessage } from '@modbm/shared';

interface ProductKitComponentsTabProps {
  productId: string;
  isEditable: boolean;
}

export const ProductKitComponentsTab: React.FC<ProductKitComponentsTabProps> = ({ productId, isEditable }) => {
  const t = useTranslations('products');
  const tCommon = useTranslations('common');
  const [refreshKey, setRefreshKey] = useState(0);
  const [slideOverState, setSlideOverState] = useState<{
    isOpen: boolean;
    componentId?: string;
    existingData?: any;
  }>({ isOpen: false });

  const columns: any[] = [
    { field: 'sequenceNumber', headerName: '#', width: 60 },
    { field: 'productNumber', headerName: t('columns.productNumber'), width: 150 },
    { field: 'name', headerName: t('columns.name'), flex: 1 },
    { field: 'parentQuantity', headerName: t('columns.parentQuantity'), type: 'numericColumn', width: 120 },
    { field: 'quantity', headerName: t('columns.quantity'), type: 'numericColumn', width: 120 },
    { field: 'fractionalBehavior', headerName: 'Fraction Rule', width: 150, valueFormatter: (p: any) => p.value?.replace('_', ' ') || '' },
    { field: 'baseUom', headerName: t('columns.baseUom'), width: 100 },
    ...(isEditable ? [{
      headerName: '',
      field: '_actions',
      width: 150,
      sortable: false,
      filter: false,
      cellRenderer: (params: any) => params.data ? (
        <div className="flex gap-1 items-center h-full">
          <button className="btn btn-sm btn-ghost min-h-0 h-8 px-2 text-[#006b5c] hover:bg-[#006b5c]/10" onClick={() => handleEdit(params.data)} title={tCommon('edit')}>
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined text-[18px]">edit</span>
            {/* eslint-enable i18next/no-literal-string */}
          </button>
          <button className="btn btn-sm btn-ghost text-red-500 hover:bg-red-50 min-h-0 h-8 px-2" onClick={() => handleDelete(params.data)} title={tCommon('delete')}>
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined text-[18px]">delete</span>
            {/* eslint-enable i18next/no-literal-string */}
          </button>
        </div>
      ) : null
    }] : [])
  ];

  const handleEdit = (row: any) => {
    setSlideOverState({
      isOpen: true,
      componentId: row.componentId,
      existingData: row,
    });
  };

  const handleDelete = async (row: any) => {
    if (!window.confirm(t('confirmRemoveComponent'))) return;
    try {
      await api.productsControllerRemoveComponent(productId, row.componentId);
      toast.success(t('toast.componentRemoved'));
      setRefreshKey(k => k + 1);
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  // Render actions now handled inside the columns definition

  return (
    <div className="flex-1 min-h-0 flex flex-col w-full h-full pb-6">
      <div className="flex-1 min-h-0 flex flex-col z-10 bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)] overflow-hidden transition-all">
        <DataGrid
          endpoint={`/api/products/${productId}/components?r=${refreshKey}`}
          columns={columns}
          gridKey="kit-components-grid"
          urlPrefix="components"
          fetchAll
          rowIdField="componentId"
          renderHeader={({ rowCount, loading }: { rowCount: number, loading: boolean }) => (
            <div className="flex items-center justify-between px-6 py-4">
              <div className="flex items-center gap-4 flex-1">
                <h2 className="text-[1.3rem] font-bold tracking-tight text-[#041627] shrink-0" style={{ fontFamily: 'Manrope, sans-serif' }}>
                  {t('tabs.kitComponents')}
                </h2>
                <div className="h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0 mx-2"></div>
                <div className="flex items-center gap-2 px-3 py-1.5 bg-[#f2f4f6] rounded-lg shrink-0">
                  <span className="text-[11px] font-bold text-[#041627] tracking-wider uppercase" style={{ fontFamily: 'Manrope, sans-serif' }}>
                    {tCommon('grid.rowCountLabel')}
                  </span>
                  <span className="text-[11px] font-bold text-[#006b5c]">
                    {loading ? '...' : rowCount.toLocaleString()}
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-3 shrink-0 ml-4">
                <button
                  className="btn btn-sm btn-primary bg-[#006b5c] hover:bg-[#005246] border-none text-white shadow-sm flex items-center gap-1.5"
                  onClick={() => setSlideOverState({ isOpen: true })}
                  disabled={!isEditable}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="material-symbols-outlined text-[16px]">add</span>
          {/* eslint-enable i18next/no-literal-string */}
                  {t('addComponent')}
                </button>
              </div>
            </div>
          )}
        />
      </div>

      <KitComponentSlideOver
        isOpen={slideOverState.isOpen}
        onClose={() => setSlideOverState({ isOpen: false })}
        productId={productId}
        componentId={slideOverState.componentId}
        existingData={slideOverState.existingData}
        onSaved={() => {
          setSlideOverState({ isOpen: false });
          setRefreshKey(k => k + 1);
        }}
      />
    </div>
  );
};

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { MobileCardField } from '@/components/shared/DataTable';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useTranslations } from 'next-intl';
import { MATCH_STATUS, PUTAWAY_STATUS } from '@modbm/shared';
import { toast } from 'react-hot-toast';
import { getErrorMessage } from '@modbm/shared';

interface AllocationSlideOverProps {
  isOpen: boolean;
  onClose: () => void;
  grLines: any[];
  onRefresh: () => void;
}

/**
 * Per-line state: tracks the fetched PO candidates and which POs are expanded.
 */
interface LineState {
  pendingLines: any[];
  loading: boolean;
  expandedPOs: Set<string>;
  allocated: boolean; // true once successfully allocated
}

export default function AllocationSlideOver({ isOpen, onClose, grLines, onRefresh }: AllocationSlideOverProps) {
  const t = useTranslations('goodsReceived');
  const [lineStates, setLineStates] = useState<Map<string, LineState>>(new Map());
  const [activeLineId, setActiveLineId] = useState<string | null>(null);
  const [localLines, setLocalLines] = useState<any[]>([]);
  // Track which line IDs have already been fetched to avoid the stale-closure race condition
  const fetchedRef = useRef<Set<string>>(new Set());

  // Initialize localLines when the slide-over opens
  useEffect(() => {
    if (isOpen) {
      // Only take lines that are currently unmatched AND not quarantined
      // ADV-086: Quarantined items must be cleared before matching
      const initialUnmatched = grLines.filter((l) => l.matchStatus !== MATCH_STATUS.MATCHED && l.putawayStatus !== PUTAWAY_STATUS.QUARANTINED);
      setLocalLines(initialUnmatched);
      if (initialUnmatched.length > 0) {
        setActiveLineId(initialUnmatched[0].goodsReceivedLineId);
      }
    } else {
      setLocalLines([]);
      setActiveLineId(null);
      setLineStates(new Map());
      fetchedRef.current = new Set();
    }
    // Intentionally only reacting to isOpen to prevent background grid refreshes from resetting the view
  }, [isOpen]);

  // We consider all localLines as our queue. Some might have been marked allocated via lineStates.
  const unmatchedLines = localLines;

  // Fetch pending POs for each line when localLines changes (we only fetch for those missing from lineStates)
  useEffect(() => {
    if (!isOpen || unmatchedLines.length === 0) return;

    for (const line of unmatchedLines) {
      // Skip if we already kicked off a fetch for this line
      if (fetchedRef.current.has(line.goodsReceivedLineId)) continue;
      fetchedRef.current.add(line.goodsReceivedLineId);

      // Initialize state for this line (loading placeholder)
      setLineStates((prev) => {
        const next = new Map(prev);
        next.set(line.goodsReceivedLineId, {
          pendingLines: [],
          loading: true,
          expandedPOs: new Set(),
          allocated: false,
        });
        return next;
      });

      api.purchaseOrdersControllerFindPendingLines({ 
        productId: line.productId, 
        vendorId: line.vendorId 
      })
        .then((data: any) => {
          const lines = Array.isArray(data) ? data : data.data || [];
          const poIds = [...new Set(lines.map((l: any) => l.purchaseOrderId))] as string[];

          setLineStates((prev) => {
            const next = new Map(prev);
            next.set(line.goodsReceivedLineId, {
              pendingLines: lines,
              loading: false,
              expandedPOs: new Set(poIds.length <= 3 ? poIds : poIds.length > 0 ? [poIds[0]] : []),
              allocated: false,
            });
            return next;
          });
        })
        .catch((err: any) => {
          reportError(err, 'AllocationSlideOver.pendingPOs');
          setLineStates((prev) => {
            const next = new Map(prev);
            next.set(line.goodsReceivedLineId, {
              pendingLines: [],
              loading: false,
              expandedPOs: new Set(),
              allocated: false,
            });
            return next;
          });
        });
    }
  }, [isOpen, unmatchedLines]);

  const toggleExpand = useCallback((lineId: string, poId: string) => {
    setLineStates((prev) => {
      const next = new Map(prev);
      const state = next.get(lineId);
      if (!state) return prev;
      const expanded = new Set(state.expandedPOs);
      if (expanded.has(poId)) expanded.delete(poId);
      else expanded.add(poId);
      next.set(lineId, { ...state, expandedPOs: expanded });
      return next;
    });
  }, []);

  const markAllocated = useCallback((lineId: string, allocatedQty: string, splitLine?: any) => {
    setLineStates((prev) => {
      const next = new Map(prev);
      const state = next.get(lineId);
      if (!state) return prev;
      next.set(lineId, { ...state, allocated: true });
      return next;
    });

    setLocalLines((prev) => {
      const idx = prev.findIndex(l => l.goodsReceivedLineId === lineId);
      if (idx === -1) return prev;

      const next = [...prev];
      // Update original line quantity to what was actually allocated
      next[idx] = { ...next[idx], quantityReceived: allocatedQty };

      let newActiveId = null;

      if (splitLine) {
        // Insert the split line right after the current line
        next.splice(idx + 1, 0, splitLine);
        // The split line becomes the new active line
        newActiveId = splitLine.goodsReceivedLineId;
      } else if (idx < next.length - 1) {
        // Auto-advance to the next line in the queue
        newActiveId = next[idx + 1].goodsReceivedLineId;
      }

      if (newActiveId) {
        setActiveLineId(newActiveId);
      }

      return next;
    });
  }, []);

  const handleAllocate = useCallback(async (grLine: any, poLine: any, qtyStr: string) => {
    const originalQuantity = parseFloat(grLine.quantityReceived || '0');
    const qty = parseFloat(qtyStr);
    if (isNaN(qty) || qty <= 0 || qty > originalQuantity) {
      toast.error(t('allocation.quantityValidationError', { max: originalQuantity }));
      return;
    }

    const hasLocationMismatch = poLine.deliveryLocationId && grLine.locationId && poLine.deliveryLocationId !== grLine.locationId;
    if (hasLocationMismatch) {
      if (!confirm(`Location Mismatch: This PO was destined for ${poLine.locationName || 'another location'}, but the goods were received here. Are you sure you want to proceed?`)) {
        return;
      }
    }

    try {
      const result = await api.goodsReceivedControllerResolveAllocation(grLine.goodsReceivedLineId, {
        purchaseOrderLineId: poLine.purchaseOrderLineId,
        allocatedQuantity: qtyStr,
      });
      // The API returns { success: true, splitLine: { ... } } if a split occurred
      const splitLineData = result?.data?.splitLine;
      
      let splitLine = null;
      if (splitLineData) {
        // Construct the new line using details from the original line
        splitLine = {
          ...grLine,
          goodsReceivedLineId: splitLineData.goodsReceivedLineId,
          quantityReceived: splitLineData.quantityReceived,
          matchStatus: splitLineData.matchStatus,
        };
      }

      markAllocated(grLine.goodsReceivedLineId, qtyStr, splitLine);
      onRefresh();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err) || t('allocation.matchError'));
    }
  }, [onRefresh, markAllocated, t]);

  if (!isOpen || unmatchedLines.length === 0) return null;

  return (
    <SlideOver isOpen={isOpen} onClose={onClose} title={`Match Received Goods (${unmatchedLines.length} line${unmatchedLines.length > 1 ? 's' : ''})`} width="max-w-4xl">
      <div className="flex flex-col gap-6">

        {/* Summary Table */}
        <div className="card mb-0">
          <div className="hidden lg:block overflow-x-auto w-full">
            <table className="table-lines w-full">
              <thead>
                <tr>
                  <th>{t('columns.receiptNo')}</th>
                  <th>{t('columns.product')}</th>
                  <th>{t('columns.supplier')}</th>
                  <th style={{ textAlign: 'right' }}>{t('columns.receivedQty', { fallback: 'Received Qty' })}</th>
                  <th style={{ width: 90, textAlign: 'center' }}>{t('columns.status', { fallback: 'Status' })}</th>
                </tr>
              </thead>
              <tbody>
                {unmatchedLines.map((line) => {
                  const state = lineStates.get(line.goodsReceivedLineId);
                  const isActive = activeLineId === line.goodsReceivedLineId;
                  return (
                    <tr 
                      key={line.goodsReceivedLineId}
                      onClick={() => setActiveLineId(line.goodsReceivedLineId)}
                      className={`cursor-pointer transition-colors ${isActive ? 'bg-[var(--bg-card-hover)] border-l-2 border-[var(--accent)]' : 'hover:bg-[var(--bg-card-hover)]/50 border-l-2 border-transparent'}`}
                    >
                      <td className="font-medium text-[var(--text-primary)]">{line.receiptNumber}</td>
                      <td>
                        <div className="font-semibold text-[var(--accent)]">{line.productNumber}</div>
                        <div className="text-xs text-[var(--text-muted)] mt-0.5">{line.productName}</div>
                      </td>
                      <td className="text-[var(--text-primary)]">{line.vendorName}</td>
                      <td className="text-right font-bold text-[var(--text-primary)] tabular-nums">
                        {parseFloat(line.quantityReceived || '0')}
                      </td>
                      <td className="text-center">
                        {state?.allocated ? (
                          <span className="badge badge-success">{t('status.allocated')}</span>
                        ) : (
                          <span className="text-xs text-[var(--text-muted)]">{t('status.pending')}</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="lg:hidden flex flex-col w-full gap-2 pt-2">
            {unmatchedLines.map((line) => {
              const state = lineStates.get(line.goodsReceivedLineId);
              const isActive = activeLineId === line.goodsReceivedLineId;
              return (
                <div
                  key={line.goodsReceivedLineId}
                  className={`transition-colors rounded-lg border p-3 flex flex-col shadow-sm ${isActive ? 'bg-[var(--bg-card-hover)] border-[var(--accent)]' : 'bg-[var(--bg-card)] border-[var(--border)]'}`}
                >
                  <div className="flex justify-between items-start gap-2 mb-2 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    <div className="font-semibold text-sm text-[var(--accent)]">
                      {line.productNumber || 'ΓÇö'}
                    </div>
                    <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">
                      {line.receiptNumber}
                    </div>
                  </div>
                  <div className="text-sm text-[var(--text-primary)] font-medium mb-3 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    {line.productName || 'ΓÇö'}
                  </div>
                  <div className="flex flex-col gap-1 border-t border-[var(--border)] pt-2 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    <MobileCardField label={t('columns.supplier')} value={line.vendorName} />
                    <MobileCardField label={t('columns.receivedQty', { fallback: 'Received Qty' })} value={
                      <span className="font-bold tabular-nums">{parseFloat(line.quantityReceived || '0')}</span>
                    } />
                    <MobileCardField label={t('columns.status', { fallback: 'Status' })} value={
                      state?.allocated ? (
                        <span className="badge badge-success">{t('status.allocated')}</span>
                      ) : (
                        <span className="text-xs text-[var(--text-muted)]">{t('status.pending')}</span>
                      )
                    } />
                  </div>
                  {isActive && state && !state.allocated && (
                    <div className="mt-4 pt-4 border-t border-[rgba(196,198,205,0.4)]">
                      <h4 className="text-xs font-bold mb-3 uppercase tracking-wider text-[var(--text-secondary)]">Eligible POs</h4>
                      <POCandidatesList grLine={line} state={state} toggleExpand={toggleExpand} handleAllocate={handleAllocate} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Per-line PO candidates */}
        <div className="hidden lg:block">
          {unmatchedLines.map((grLine) => {
            if (grLine.goodsReceivedLineId !== activeLineId) return null;
            
            const state = lineStates.get(grLine.goodsReceivedLineId);
            if (!state || state.allocated) return null;

            const originalQuantity = parseFloat(grLine.quantityReceived || '0');

            return (
              <div key={grLine.goodsReceivedLineId}>
                {/* Section header */}
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-2 mb-4 p-3 bg-[var(--bg-card)] rounded-lg border border-[var(--border)] lg:border-none lg:p-0 lg:bg-transparent">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-bold text-[var(--accent)]">{grLine.productNumber}</span>
                    <span className="hidden lg:inline text-[var(--text-muted)]">ΓÇö</span>
                    <span className="text-sm text-[var(--text-primary)] w-full lg:w-auto">{grLine.productName}</span>
                  </div>
                  
                  <div className="flex flex-wrap items-center justify-between lg:justify-end gap-4 mt-2 lg:mt-0 pt-2 lg:pt-0 border-t border-[var(--border)] lg:border-none w-full lg:w-auto">
                    <span className="text-xs text-[var(--text-secondary)]">
                      {t('allocation.receivedAt')} <span className="font-medium text-[var(--text-primary)]">{grLine.locationName || t('allocation.unknown')}</span>
                    </span>
                    <span className="text-xs font-semibold px-2 py-1 bg-[var(--bg-secondary)] rounded-md text-[var(--text-primary)] tabular-nums shrink-0">
                      {t('allocation.qty')} {originalQuantity}
                    </span>
                  </div>
                </div>

                <POCandidatesList grLine={grLine} state={state} toggleExpand={toggleExpand} handleAllocate={handleAllocate} />
              </div>
            );
          })}
        </div>

      </div>
    </SlideOver>
  );
}

function POCandidatesList({
  grLine,
  state,
  toggleExpand,
  handleAllocate
}: {
  grLine: any;
  state: any;
  toggleExpand: (lineId: string, poId: string) => void;
  handleAllocate: (grLine: any, poLine: any, qtyStr: string) => void;
}) {
  const t = useTranslations('goodsReceived');
  const originalQuantity = parseFloat(grLine.quantityReceived || '0');

  // Group pending lines by PO
  const poGroups = new Map<string, any>();
  for (const line of state.pendingLines) {
    if (!poGroups.has(line.purchaseOrderId)) {
      poGroups.set(line.purchaseOrderId, {
        purchaseOrderId: line.purchaseOrderId,
        orderNumber: line.orderNumber,
        locationName: line.locationName,
        lines: [],
      });
    }
    poGroups.get(line.purchaseOrderId)!.lines.push(line);
  }
  const groups = Array.from(poGroups.values());

  if (state.loading) {
    return (
      <div className="p-6 text-center text-[var(--text-muted)] border border-[var(--border)] rounded-md bg-[var(--bg-card)]">
        {t('allocation.loadingEligible')}
      </div>
    );
  }

  if (groups.length === 0) {
    return (
      <div className="p-6 text-center text-[var(--text-muted)] border border-[var(--border)] rounded-md bg-[var(--bg-card)]">
        {t('allocation.noPendingPOs')}
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      {groups.map((group) => {
        const isExpanded = state.expandedPOs.has(group.purchaseOrderId);
        return (
          <div key={group.purchaseOrderId} style={{ borderRadius: 8, border: '1px solid var(--border)', overflow: 'hidden', background: 'var(--bg-card)' }}>
            {/* Card Header */}
            <button
              onClick={() => toggleExpand(grLine.goodsReceivedLineId, group.purchaseOrderId)}
              style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 16px', background: 'none', border: 'none', cursor: 'pointer', textAlign: 'left' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined" style={{ fontSize: 18, transition: 'transform 0.15s', transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)', color: 'var(--text-muted)' }}>
                  chevron_right
                </span>
                <span style={{ fontWeight: 700, color: 'var(--accent)', fontSize: 14 }}>
                  {group.orderNumber}
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                {grLine.locationName && group.locationName && grLine.locationName !== group.locationName && (
                  <span className="badge badge-sm badge-warning">{t('allocation.locationMismatch')}</span>
                )}
                <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                  {t('allocation.destination')} <span className="font-medium text-[var(--text-primary)]">{group.locationName || t('allocation.unknown')}</span>
                </div>
              </div>
            </button>

            {/* Expanded Lines */}
            {isExpanded && (
              <div style={{ borderTop: '1px solid var(--border)' }}>
                <div className="hidden lg:block overflow-x-auto">
                  <table className="table-lines w-full">
                    <thead>
                      <tr>
                        <th>{t('columns.ordered', { fallback: 'Ordered' })}</th>
                        <th>{t('columns.received', { fallback: 'Received' })}</th>
                        <th>{t('columns.remaining', { fallback: 'Remaining' })}</th>
                        <th style={{ width: 160, textAlign: 'center' }}>{t('columns.allocate', { fallback: 'Allocate' })}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {group.lines.map((poLine: any) => (
                        <POLineRow
                          key={poLine.purchaseOrderLineId}
                          line={poLine}
                          originalQuantity={originalQuantity}
                          onAllocate={(qty) => handleAllocate(grLine, poLine, qty)}
                        />
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="lg:hidden flex flex-col w-full divide-y divide-[var(--border)]">
                  {group.lines.map((poLine: any) => (
                    <POLineMobileCard
                      key={poLine.purchaseOrderLineId}
                      line={poLine}
                      originalQuantity={originalQuantity}
                      onAllocate={(qty) => handleAllocate(grLine, poLine, qty)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function POLineRow({ line, originalQuantity, onAllocate }: { line: any; originalQuantity: number; onAllocate: (qty: string) => void }) {
  const t = useTranslations('goodsReceived');
  const ordered = parseFloat(line.quantity || '0');
  const received = parseFloat(line.quantityReceived || '0');
  const remaining = Math.max(0, ordered - received);

  const suggestedQty = Math.min(originalQuantity, remaining);
  const [qty, setQty] = useState(suggestedQty > 0 ? suggestedQty.toString() : originalQuantity.toString());
  const [isAllocating, setIsAllocating] = useState(false);

  return (
    <tr>
      <td className="tabular-nums">{ordered}</td>
      <td className="tabular-nums text-[var(--text-primary)]">{received}</td>
      <td className="tabular-nums font-bold text-[var(--text-primary)]">{remaining}</td>
      <td className="text-right">
        <div className="flex items-center justify-end gap-1">
          <input
            type="number"
            step="0.01"
            min="0.01"
            max={originalQuantity}
            className="input text-right"
            style={{ width: '70px', padding: '2px 4px', height: '26px', fontSize: '12px' }}
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
          <button
            onClick={async () => {
              setIsAllocating(true);
              await onAllocate(qty);
              setIsAllocating(false);
            }}
            disabled={isAllocating || !qty}
            className="btn btn-primary btn-sm"
            style={{ padding: '2px 8px', height: '26px', fontSize: '11px' }}
          >
            {isAllocating ? t('allocation.allocating') : t('allocation.match')}
          </button>
        </div>
      </td>
    </tr>
  );
}

function POLineMobileCard({ line, originalQuantity, onAllocate }: { line: any; originalQuantity: number; onAllocate: (qty: string) => void }) {
  const t = useTranslations('goodsReceived');
  const ordered = parseFloat(line.quantity || '0');
  const received = parseFloat(line.quantityReceived || '0');
  const remaining = Math.max(0, ordered - received);

  const suggestedQty = Math.min(originalQuantity, remaining);
  const [qty, setQty] = useState(suggestedQty > 0 ? suggestedQty.toString() : originalQuantity.toString());
  const [isAllocating, setIsAllocating] = useState(false);

  return (
    <div className="flex flex-col gap-2 p-4 bg-[var(--bg-secondary)]">
      <div className="flex items-center justify-between gap-4">
        <MobileCardField className="flex-1 border-0 py-0" label={t('columns.ordered', { fallback: 'Ordered' })} value={ordered} />
        <MobileCardField className="flex-1 border-0 py-0" label={t('columns.received', { fallback: 'Received' })} value={received} />
      </div>
      <div className="flex flex-col gap-2 border-t border-[var(--border)] pt-3 mt-1">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500">{t('columns.remaining', { fallback: 'Remaining' })}</span>
          <span className="text-sm font-bold text-[var(--text-primary)] tabular-nums">{remaining}</span>
        </div>
        <div className="flex items-center justify-end gap-2 mt-2">
          <input
            type="number"
            step="0.01"
            min="0.01"
            max={originalQuantity}
            className="input text-right"
            style={{ width: '80px', padding: '6px 8px', height: '32px', fontSize: '13px' }}
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
          <button
            onClick={async () => {
              setIsAllocating(true);
              await onAllocate(qty);
              setIsAllocating(false);
            }}
            disabled={isAllocating || !qty}
            className="btn btn-primary"
            style={{ padding: '6px 16px', height: '32px', fontSize: '13px' }}
          >
            {isAllocating ? t('allocation.allocating') : t('allocation.match')}
          </button>
        </div>
      </div>
    </div>
  );
}

